    {
      "draft_id": "D0002",
      "claim_type": "fiscal_measure",
      "actor": "Mexico's fiscal authorities",
      "action": "applied differentiated percentages and monetary amounts of fiscal stimulus to automotive fuels",
      "mechanism": "fuel-specific excise-tax stimulus rates and per-liter tax reductions",
      "outcome": "provided a 26.96% stimulus for gasoline below 91 octane, no stimulus for gasoline at or above 91 octane and non-fossil fuels, and a 59.77% stimulus for diesel; the corresponding amounts were 1.4803 pesos/liter for lower-octane gasoline, 0 pesos/liter for higher-octane gasoline and non-fossil fuels, and 3.6071 pesos/liter for diesel",
      "dates": {
        "applicable_period_start": "2022-12-10",
        "applicable_period_end": "2022-12-16"
      },
      "quantities": {
        "stimulus_percentages": {
          "gasoline_below_91_octane": "26.96%",
          "gasoline_at_or_above_91_octane_and_non_fossil_fuels": "0.00%",
          "diesel": "59.77%"
        },
        "stimulus_amounts_pesos_per_liter": {
          "gasoline_below_91_octane": "1.4803",
          "gasoline_at_or_above_91_octane_and_non_fossil_fuels": "0.0000",
          "diesel": "3.6071"
        }
      },
      "attribution": "Amounts and percentages are specified in Articles First and Second of the official agreement.",
      "period_fit": "direct; all listed values are specified for 10–16 December 2022",
      "limitations": "The passage does not explain the policy's targeting rationale, beneficiaries, fiscal burden, price pass-through, or realized effects.",
