      "claim_type": "tax_rate_schedule",
      "actor": "Mexico's fiscal authorities",
      "action": "set reduced excise-tax quotas for automotive fuels",
      "mechanism": "fuel-specific statutory per-liter quotas",
      "outcome": "set quotas at 4.0114 pesos/liter for gasoline below 91 octane, 4.6375 pesos/liter for gasoline at or above 91 octane and non-fossil fuels, and 2.4283 pesos/liter for diesel",
      "dates": {
        "applicable_period_start": "2022-12-10",
        "applicable_period_end": "2022-12-16"
      },
      "quantities": {
